const accounts={farmer:{email:'farmer@demo.in',password:'Farmer@123',name:'Ramesh Patil',label:'Farmer'},staff:{email:'staff@demo.in',password:'Staff@123',name:'Sunita Deshmukh',label:'Centre staff'},admin:{email:'admin@demo.in',password:'Admin@123',name:'Amit Kulkarni',label:'Administrator'}};
const loginScreen=document.querySelector('#login-screen'),appScreen=document.querySelector('#app-screen'),loginLanguage=document.querySelector('#login-language'),loginError=document.querySelector('#login-error');
const languageSelectors=[document.querySelector('#login-language-select'),document.querySelector('#language-select')];
const uiWords={hi:{Overview:'अवलोकन',Schedules:'समय-सारणी',Messages:'संदेश','Centre queue':'केंद्र कतार',Administration:'प्रशासन','New schedule':'नई समय-सारणी',Farmer:'किसान','Centre staff':'केंद्र कर्मचारी',Administrator:'प्रशासक'},mr:{Overview:'आढावा',Schedules:'वेळापत्रक',Messages:'संदेश','Centre queue':'केंद्र रांग',Administration:'प्रशासन','New schedule':'नवे वेळापत्रक',Farmer:'शेतकरी','Centre staff':'केंद्र कर्मचारी',Administrator:'प्रशासक'}};const tr=value=>uiWords[window.PROCUREFLOW_LANGUAGE]?.[value]||value;
languageSelectors.forEach(select=>{select.value=window.PROCUREFLOW_LANGUAGE;select.addEventListener('change',()=>{localStorage.setItem('procureflow-language',select.value);location.reload()})});
const toast=message=>{const box=document.querySelector('#toast');box.textContent=message;box.hidden=false;setTimeout(()=>box.hidden=true,3000)};
let currentRole=null;
function navFor(role){const links=role==='farmer'?[['overview','Overview'],['schedules','Schedules'],['messages','Messages']]:role==='staff'?[['overview','Centre queue'],['messages','Messages']]:[['overview','Administration'],['new-schedule','New schedule'],['messages','Messages']];document.querySelector('#primary-nav').innerHTML=links.map(([target,label])=>`<button class="nav-role" data-nav="${target}">${tr(label)}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();showRoute(button.dataset.nav)}))}
function showRoute(route){if(!currentRole)return;if(route==='new-schedule'){document.querySelector('#schedule-dialog').showModal();return}const view=route==='messages'?'messages':currentRole;document.querySelectorAll('[data-view]').forEach(section=>section.hidden=section.dataset.view!==view);document.querySelectorAll('.nav-role').forEach(link=>link.classList.toggle('active',link.dataset.nav===route||(route==='overview'&&link.dataset.nav==='overview')));if(route==='schedules')setTimeout(()=>document.querySelector('#schedules').scrollIntoView({behavior:'smooth'}),0);location.hash=route}
function enterApp(role){currentRole=role;const account=accounts[role];localStorage.setItem('procureflow-session',role);loginScreen.hidden=true;loginLanguage.hidden=true;appScreen.hidden=false;document.querySelector('#user-name').textContent=account.name;document.querySelector('#user-role').textContent=tr(account.label);document.title=`${tr(account.label)} · ProcureFlow`;navFor(role);showRoute('overview');renderToken()}
function signOut(){localStorage.removeItem('procureflow-session');currentRole=null;appScreen.hidden=true;loginScreen.hidden=false;loginLanguage.hidden=false;document.querySelector('#login-form').reset();history.replaceState(null,'','#');document.title='Sign in · ProcureFlow'}
document.querySelectorAll('[data-demo]').forEach(button=>button.addEventListener('click',()=>{const account=accounts[button.dataset.demo];document.querySelector('#login-email').value=account.email;document.querySelector('#login-password').value=account.password;loginError.hidden=true}));
document.querySelector('#login-form').addEventListener('submit',event=>{event.preventDefault();const email=document.querySelector('#login-email').value.trim().toLowerCase(),password=document.querySelector('#login-password').value;const match=Object.entries(accounts).find(([,a])=>a.email===email&&a.password===password);if(!match){loginError.hidden=false;return}loginError.hidden=true;enterApp(match[0])});
document.querySelector('#sign-out').addEventListener('click',signOut);
document.querySelector('[data-scroll-schedules]').addEventListener('click',()=>document.querySelector('#schedules').scrollIntoView({behavior:'smooth'}));

const bookingDialog=document.querySelector('#booking-dialog');let selectedCrop='Wheat',selectedDate='08 Sep 2026';document.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{selectedCrop=button.dataset.crop;selectedDate=button.dataset.date;document.querySelector('#dialog-title').textContent=`${selectedCrop} procurement`;bookingDialog.showModal()}));
document.querySelector('#confirm-booking').addEventListener('click',event=>{const form=bookingDialog.querySelector('form');if(!form.checkValidity()){event.preventDefault();form.reportValidity();return}const saved={token:'PF-0809-01-001',crop:selectedCrop,date:selectedDate,status:'booked',quantity:document.querySelector('#quantity').value};localStorage.setItem('procureflow-token',JSON.stringify(saved));setTimeout(()=>{renderToken();toast('Token confirmed and notification created')},0)});
function renderToken(){const saved=JSON.parse(localStorage.getItem('procureflow-token')||'null');const active=document.querySelector('#active-token');if(!saved){active.className='empty-card';active.innerHTML='<span class="empty-icon">#</span><div><h2>No active token</h2><p>Choose an open schedule and confirm your eligibility to reserve a visit.</p></div>';document.querySelector('#active-count').textContent='0';return}active.className='active-token';active.innerHTML=`<div><span class="eyebrow">Active token</span><h2>${saved.token}</h2></div><div class="token-summary"><span><small>Commodity</small>${saved.crop}</span><span><small>Date</small>${saved.date}</span><span><small>Status</small>${saved.status.replace('_',' ')}</span></div><button class="button light" id="cancel-token">Cancel token</button>`;document.querySelector('#active-count').textContent=saved.status==='completed'?'0':'1';document.querySelector('#cancel-token').addEventListener('click',()=>{localStorage.removeItem('procureflow-token');renderToken();toast('Token cancelled')});const message=`<span class="empty-icon">✓</span><div><h2>Token ${saved.token} confirmed</h2><p>${saved.crop} · ${saved.date} · ${saved.quantity||5} quintals</p></div>`;document.querySelector('#farmer-message').innerHTML=message;document.querySelector('#messages-content').innerHTML=message}

const transitions=[['booked','Booked','Check in'],['checked_in','Checked in','Start'],['serving','Serving','Complete'],['completed','Completed','Completed']];let step=Number(localStorage.getItem('procureflow-queue-step')||0);function paintQueue(){const [state,label,action]=transitions[step];const status=document.querySelector('#demo-status'),button=document.querySelector('#advance-status');status.className=`large-status ${state}`;status.textContent=label;button.textContent=action;button.disabled=step===3;document.querySelector('#staff-completed').textContent=step===3?'1':'0';document.querySelector('#staff-waiting').textContent=step===3?'0':'1';document.querySelector('#complete-count').textContent=step===3?'1':'0'}
document.querySelector('#advance-status').addEventListener('click',()=>{if(step<3)step++;localStorage.setItem('procureflow-queue-step',step);paintQueue();const label=transitions[step][1];const saved=JSON.parse(localStorage.getItem('procureflow-token')||'null');if(saved){saved.status=transitions[step][0];localStorage.setItem('procureflow-token',JSON.stringify(saved))}toast(`Token status: ${label}`)});paintQueue();

const scheduleDialog=document.querySelector('#schedule-dialog');document.querySelector('#create-demo-schedule').addEventListener('click',()=>scheduleDialog.showModal());document.querySelector('#publish-schedule').addEventListener('click',event=>{const form=document.querySelector('#schedule-form');if(!form.checkValidity()){event.preventDefault();form.reportValidity();return}const crop=document.querySelector('#new-crop').value,date=new Date(`${document.querySelector('#new-date').value}T00:00:00`).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),capacity=document.querySelector('#new-capacity').value;document.querySelector('#admin-schedules').insertAdjacentHTML('beforeend',`<tr><td>${date}</td><td>${crop}</td><td>Shirur Procurement Centre</td><td>0 / ${capacity}</td><td><span class="large-status open">Open</span></td></tr>`);document.querySelector('#schedule-count').textContent=String(Number(document.querySelector('#schedule-count').textContent)+1);setTimeout(()=>toast('Schedule published'),0)});

const savedRole=localStorage.getItem('procureflow-session');if(accounts[savedRole])enterApp(savedRole);
